import { OrderRepository } from './repository';
import { ListRequest, Page } from './types';
export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}
  list(request: ListRequest): Page {
    const { tenant, limit, cursor } = request;
    if (typeof tenant !== 'string' || !tenant || !Number.isInteger(limit) || limit < 1 || limit > 100) {
      throw new Error('invalid request');
    }
    let after: { createdAt: string; id: string } | undefined;
    if (cursor !== undefined) {
      const parts = typeof cursor === 'string' ? cursor.split('|') : [];
      if (parts.length !== 2 || !parts[0] || !parts[1]) throw new Error('invalid request');
      after = { createdAt: parts[0], id: parts[1] };
    }
    const found = this.repository.list(tenant, after, limit + 1);
    const items = found.slice(0, limit);
    const last = items[items.length - 1];
    return {
      items,
      nextCursor: found.length > limit && last ? last.createdAt + '|' + last.id : null,
    };
  }
}

