import { Order } from './types';
const cmp = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);
export class OrderRepository {
  constructor(private readonly rows: Order[]) {}
  list(tenant: string, after?: { createdAt: string; id: string }, max?: number): Order[] {
    const out = this.rows
      .filter(row => row.tenant === tenant)
      .filter(row => !after || cmp(row.createdAt, after.createdAt) > 0 ||
        (row.createdAt === after.createdAt && cmp(row.id, after.id) > 0))
      .sort((a, b) => cmp(a.createdAt, b.createdAt) || cmp(a.id, b.id));
    return max === undefined ? out : out.slice(0, max);
  }
}
